{"source":"import sys
import csv
import json
import re
from decimal import Decimal, ROUND_HALF_UP

TWO = Decimal("0.01")


def normalize_category(raw):
    collapsed = re.sub(r"\s+", " ", raw).strip()
    collapsed = collapsed.casefold()
    if not collapsed:
        return "uncategorized"
    return collapsed


def money(value):
    return value.quantize(TWO, rounding=ROUND_HALF_UP)


def fmt(total):
    q = money(total)
    if q == 0:
        q = Decimal("0.00")
    return str(q)


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2

    with open(argv[1], "rb") as fh:
        text = fh.read().decode("utf-8")

    categories = {}
    total = Decimal("0")

    reader = csv.DictReader(text.splitlines())
    if reader.fieldnames is None:
        # empty file (no header) -> treat as header-only
        result = {"categories": [], "total": "0.00"}
        print(json.dumps(result, separators=(",", ":")))
        return 0

    for row in reader:
        status = (row.get("status") or "").strip().casefold()
        if status != "paid":
            continue

        category = normalize_category(row.get("category") or "")
        amount = Decimal((row.get("amount") or "").strip())
        rounded = money(amount)

        categories[category] = categories.get(category, Decimal("0")) + rounded
        total += rounded

    ordered = sorted(categories.items(), key=lambda kv: kv[0])
    out_categories = [
        {"category": name, "total": fmt(total_sum)} for name, total_sum in ordered
    ]

    result = {"categories": out_categories, "total": fmt(total)}
    print(json.dumps(result, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))"}

